   var tools=new Grid{Margin=new Thickness(0,0,0,22)};tools.ColumnDefinitions.Add(new ColumnDefinition());tools.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(150)});tools.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(145)});
