   filter.ItemsSource=new[]{"Все задачи","На сегодня","Без даты","Просрочено"};filter.SelectedIndex=0;System.Windows.Automation.AutomationProperties.SetName(filter,"Фильтр по дате");Grid.SetColumn(filter,2);tools.Children.Add(filter);importance.SelectionChanged+=delegate{if(!rendering)Refresh();};filter.SelectionChanged+=delegate{if(!rendering)Refresh();};DockPanel.SetDock(tools,Dock.Top);page.Children.Add(tools);
