  void UpdateStatus(){sync.Text=drive.IsConnected?(cloudStatus==""?"Google Диск подключён":cloudStatus):store.Status;}
  async void RunCloudSync(){if(cloudBusy||!drive.IsConnected)return;cloudBusy=true;lastCloud=DateTime.UtcNow;cloudStatus="Синхронизация с Google Диском…";UpdateStatus();try{int epoch=drive.Epoch;var incoming=await drive.PullAsync();if(epoch!=drive.Epoch)return;if(store.MergeRecords(incoming))Refresh();await drive.PushAsync(store.AllRecords);cloudStatus="Google Диск · синхронизировано "+DateTime.Now.ToString("HH:mm");}catch(Exception e){cloudStatus="Локально сохранено · "+e.Message;}finally{cloudBusy=false;UpdateStatus();}}
  void Go(string next,string name=""){rendering=true;view=next;project=name;search.Clear();importance.SelectedIndex=0;filter.SelectedIndex=0;rendering=false;Refresh();}
  void RenderRail(){
