   UI.Gap(rail,28);var heading=new DockPanel();var add=UI.Button("+",()=>ProjectDialog(null));add.Padding=new Thickness(7,2,7,2);add.BorderThickness=new Thickness(0);add.Background=Brushes.Transparent;add.ToolTip="Создать проект";DockPanel.SetDock(add,Dock.Right);heading.Children.Add(add);var label=UI.Text("ПРОЕКТЫ",9,UI.Muted,true);label.Margin=new Thickness(8,0,0,0);heading.Children.Add(label);rail.Children.Add(heading);UI.Gap(rail,9);
   foreach(string name in store.ProjectNames){string key=name;int count=Tasks.Count(t=>t.category==key&&!t.completed);var b=Nav("●   "+key+(count>0?"   "+count:""),()=>Go(view,key),project==key);b.Foreground=UI.B(UI.ColorFor(key));var menu=new ContextMenu();var rename=new MenuItem{Header="Переименовать"};rename.Click+=delegate{ProjectDialog(key);};menu.Items.Add(rename);var remove=new MenuItem{Header="Удалить проект"};remove.Click+=delegate{if(MessageBox.Show(this,"Удалить проект «"+key+"»? Его задачи останутся в списке без проекта.","Ритм",MessageBoxButton.YesNo)==MessageBoxResult.Yes){try{store.DeleteProject(key);project="";Refresh();RunCloudSync();}catch(Exception e){Error(e);}}};menu.Items.Add(remove);b.ContextMenu=menu;rail.Children.Add(b);}
   if(!store.ProjectNames.Any()){var text=UI.Text("Создайте проект, чтобы собрать связанные задачи.",11,UI.Muted);text.Margin=new Thickness(8,7,8,8);rail.Children.Add(text);}
   UI.Gap(rail,10);rail.Children.Add(Nav("Без проекта",()=>Go(view,"Без проекта"),project=="Без проекта"));
  }
  Button Nav(string text,Action action,bool active){var b=UI.Button(text,action);b.Background=active?UI.B("#E9EDE1"):Brushes.Transparent;b.BorderThickness=new Thickness(0);b.HorizontalContentAlignment=HorizontalAlignment.Left;b.Margin=new Thickness(0,2,0,2);return b;}
  void ProjectDialog(string old){var w=new Window{Owner=this,Title=old==null?"Новый проект":"Переименовать проект",Width=420,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=UI.Canvas};var p=new StackPanel{Margin=new Thickness(24)};w.Content=p;p.Children.Add(UI.Text(old==null?"Новый проект":"Название проекта",22,null,true));UI.Gap(p,17);var name=UI.Input(old??"",50);System.Windows.Automation.AutomationProperties.SetName(name,"Название проекта");p.Children.Add(name);UI.Gap(p,20);p.Children.Add(UI.Button("Сохранить",()=>{try{if(old==null)store.CreateProject(name.Text);else store.RenameProject(old,name.Text);if(project==old)project=name.Text.Trim();w.DialogResult=true;}catch(Exception e){MessageBox.Show(w,e.Message,"Ритм");}},true));w.Loaded+=delegate{name.Focus();name.SelectAll();};w.ShowDialog();Refresh();RunCloudSync();}
  List<TaskItem> Filtered(){string q=search.Text.Trim().ToLowerInvariant(),today=UI.Date(DateTime.Today);return Tasks.Where(t=>(project==""||t.category==project)&&(q==""||(t.title+" "+t.description+" "+t.category).ToLowerInvariant().Contains(q))&&(importance.SelectedIndex==0||t.priority==importance.SelectedIndex)&&(filter.SelectedIndex==0||filter.SelectedIndex==1&&t.date==today||filter.SelectedIndex==2&&t.date==null||filter.SelectedIndex==3&&!t.completed&&t.date!=null&&string.CompareOrdinal(t.date,today)<0)).OrderBy(t=>t.completed).ThenBy(t=>t.priority).ThenBy(t=>t.date??"9999").ThenBy(t=>t.createdAt).ToList();}
  public void Refresh(){if(rendering)return;rendering=true;try{RenderRail();title.Text=project!=""?project:view=="board"?"Доска":view=="calendar"?"Календарь":"Все задачи";var tasks=Filtered();caption.Text="Всего: "+tasks.Count+" · Открыто: "+tasks.Count(t=>!t.completed);content.Content=view=="board"?Board(tasks):view=="calendar"?Calendar(tasks):List(tasks);UpdateStatus();}finally{rendering=false;}}
  UIElement Board(List<TaskItem> tasks){var grid=new Grid();for(int c=0;c<3;c++){grid.ColumnDefinitions.Add(new ColumnDefinition());if(c<2)grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(16)});}var states=new[]{"todo","doing","done"};var labels=new[]{"К выполнению","В работе","Готово"};for(int i=0;i<3;i++){string status=states[i];var entries=tasks.Where(t=>t.status==status).ToList();var dock=new DockPanel();var h=new DockPanel{Margin=new Thickness(1,0,0,15)};var add=UI.Button("+",()=>EditNew(status,null));add.Background=Brushes.Transparent;add.BorderThickness=new Thickness(0);add.Padding=new Thickness(6,1,6,1);add.ToolTip="Добавить задачу";DockPanel.SetDock(add,Dock.Right);h.Children.Add(add);h.Children.Add(UI.Text(labels[i]+"   "+entries.Count,12,UI.Muted,true));DockPanel.SetDock(h,Dock.Top);dock.Children.Add(h);var cards=new StackPanel();foreach(var t in entries)cards.Children.Add(TaskCard(t));if(entries.Count==0){var empty=UI.Text("Перетащите задачу сюда\nили нажмите +",11,UI.Muted);empty.Margin=new Thickness(8,22,8,0);cards.Children.Add(empty);}dock.Children.Add(new ScrollViewer{Content=cards,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var drop=new Border{Child=dock,Background=UI.B("#F7F8F1"),CornerRadius=new CornerRadius(9),Padding=new Thickness(14),AllowDrop=true};drop.DragOver+=(s,e)=>{e.Effects=e.Data.GetDataPresent(DataFormats.StringFormat)?DragDropEffects.Move:DragDropEffects.None;e.Handled=true;};drop.Drop+=(s,e)=>{string id=e.Data.GetData(DataFormats.StringFormat) as string;var task=Tasks.FirstOrDefault(t=>t.id==id);if(task!=null&&task.status!=status){task.status=status;task.completed=status=="done";Persist(task);}};Grid.SetColumn(drop,i*2);grid.Children.Add(drop);}return grid;}
  UIElement TaskCard(TaskItem task){var p=new StackPanel();var top=new DockPanel();var menu=UI.Button("⋯",()=>Edit(task));menu.Background=Brushes.Transparent;menu.BorderThickness=new Thickness(0);menu.Padding=new Thickness(4,0,4,0);menu.Margin=new Thickness(0);DockPanel.SetDock(menu,Dock.Right);top.Children.Add(menu);top.Children.Add(UI.Text(task.category=="Без проекта"?" ":task.category,10,UI.B(UI.ColorFor(task.category))));p.Children.Add(top);UI.Gap(p,11);var name=UI.Text(task.title,14,null,true);if(task.completed)name.Foreground=UI.Muted;p.Children.Add(name);if(!string.IsNullOrWhiteSpace(task.description)){UI.Gap(p,7);var desc=UI.Text(task.description.Replace("\r","").Replace("\n"," "),11,UI.Muted);desc.MaxHeight=34;desc.TextTrimming=TextTrimming.CharacterEllipsis;p.Children.Add(desc);}var tags=new List<string>();if(task.date!=null)tags.Add(UI.DisplayDate(task.date));if(task.priority<3)tags.Add(UI.Priority(task.priority));if(task.subtasks.Count>0)tags.Add(task.subtasks.Count(s=>s.done)+"/"+task.subtasks.Count);if(tags.Any()){UI.Gap(p,15);p.Children.Add(UI.Text(string.Join("  ·  ",tags),10,UI.Muted));}var card=UI.Card(p,null,new Thickness(15));card.Margin=new Thickness(0,0,0,11);card.Cursor=Cursors.Hand;AttachDrag(card,task,()=>Edit(task));var context=new ContextMenu();foreach(var pair in new[]{new[]{"todo","К выполнению"},new[]{"doing","В работе"},new[]{"done","Готово"}}){string state=pair[0];var item=new MenuItem{Header=pair[1]};item.Click+=delegate{var t=task.Clone();t.status=state;t.completed=state=="done";Persist(t);};context.Items.Add(item);}card.ContextMenu=context;return card;}
  void AttachDrag(FrameworkElement element,TaskItem task,Action click){Point start=new Point();bool dragging=false;element.PreviewMouseLeftButtonDown+=(s,e)=>{start=e.GetPosition(element);dragging=false;};element.PreviewMouseMove+=(s,e)=>{if(e.LeftButton!=MouseButtonState.Pressed||dragging)return;Point pos=e.GetPosition(element);if(Math.Abs(pos.X-start.X)>SystemParameters.MinimumHorizontalDragDistance||Math.Abs(pos.Y-start.Y)>SystemParameters.MinimumVerticalDragDistance){dragging=true;DragDrop.DoDragDrop(element,task.id,DragDropEffects.Move);e.Handled=true;}};element.MouseLeftButtonUp+=(s,e)=>{if(!dragging&&!(e.OriginalSource is Button)){click();e.Handled=true;}};}
  UIElement List(List<TaskItem> tasks){var p=new StackPanel();foreach(var task in tasks){var current=task;var row=new DockPanel{Margin=new Thickness(0,0,0,1)};var check=new CheckBox{IsChecked=task.completed,Margin=new Thickness(8,17,12,0),VerticalAlignment=VerticalAlignment.Top};System.Windows.Automation.AutomationProperties.SetName(check,"Выполнить: "+task.title);check.Click+=delegate{var t=current.Clone();t.completed=check.IsChecked==true;t.status=t.completed?"done":"todo";Persist(t);};DockPanel.SetDock(check,Dock.Left);row.Children.Add(check);var b=UI.Button("",()=>Edit(current));var info=new StackPanel{Margin=new Thickness(0,4,0,4)};info.Children.Add(UI.Text(task.title,14,null,true));UI.Gap(info,5);info.Children.Add(UI.Text(task.category+" · "+UI.DisplayDate(task.date)+" · "+(task.status=="doing"?"В работе":task.completed?"Готово":"К выполнению"),10,UI.Muted));b.Content=info;b.HorizontalContentAlignment=HorizontalAlignment.Left;b.BorderThickness=new Thickness(0);b.Background=UI.Paper;row.Children.Add(b);p.Children.Add(row);}if(tasks.Count==0)p.Children.Add(Empty("Пока нет задач","Добавьте первую задачу или измените фильтры."));return new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
  UIElement Calendar(List<TaskItem> tasks){var root=new DockPanel();var bar=new DockPanel{Margin=new Thickness(0,0,0,18)};var period=new StackPanel{Orientation=Orientation.Horizontal};period.Children.Add(UI.Button("Месяц",()=>{week=false;Refresh();}));period.Children.Add(UI.Button("Неделя",()=>{week=true;Refresh();}));DockPanel.SetDock(period,Dock.Right);bar.Children.Add(period);var controls=new StackPanel{Orientation=Orientation.Horizontal};var month=UI.Text(anchor.ToString("MMMM yyyy",new CultureInfo("ru-RU")),17,null,true);month.Margin=new Thickness(0,0,15,0);controls.Children.Add(month);controls.Children.Add(UI.Button("‹",()=>{anchor=week?anchor.AddDays(-7):new DateTime(anchor.Year,anchor.Month,1).AddMonths(-1);Refresh();}));controls.Children.Add(UI.Button("›",()=>{anchor=week?anchor.AddDays(7):new DateTime(anchor.Year,anchor.Month,1).AddMonths(1);Refresh();}));controls.Children.Add(UI.Button("Сегодня",()=>{anchor=selected=DateTime.Today;Refresh();}));bar.Children.Add(controls);DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);var p=new StackPanel();var weekdays=new UniformGrid{Columns=7};foreach(var d in new[]{"Пн","Вт","Ср","Чт","Пт","Сб","Вс"}){var text=UI.Text(d,11,UI.Muted);text.Margin=new Thickness(10,0,0,10);weekdays.Children.Add(text);}p.Children.Add(weekdays);DateTime first=week?anchor:new DateTime(anchor.Year,anchor.Month,1);first=first.AddDays(-((int)first.DayOfWeek+6)%7);int count=week?7:(int)Math.Ceiling((((int)new DateTime(anchor.Year,anchor.Month,1).DayOfWeek+6)%7+DateTime.DaysInMonth(anchor.Year,anchor.Month))/7.0)*7;var grid=new UniformGrid{Columns=7};for(int i=0;i<count;i++){DateTime day=first.AddDays(i);string key=UI.Date(day);var cell=new StackPanel();var dayButton=UI.Button(day.Day.ToString(),()=>EditNew("todo",key));dayButton.Padding=new Thickness(5,3,5,3);dayButton.BorderThickness=new Thickness(0);dayButton.HorizontalAlignment=HorizontalAlignment.Left;dayButton.Background=day.Date==DateTime.Today?UI.Accent:Brushes.Transparent;dayButton.Foreground=day.Date==DateTime.Today?Brushes.White:UI.Muted;dayButton.ToolTip="Добавить задачу на "+day.ToString("d MMMM");cell.Children.Add(dayButton);foreach(var item in tasks.Where(t=>t.date==key)){var t=item;var b=UI.Button(t.title,()=>Edit(t));b.Padding=new Thickness(4,5,4,5);b.Margin=new Thickness(0,4,0,0);b.FontSize=10;b.Background=UI.B("#E9EDE1");b.BorderThickness=new Thickness(0);b.HorizontalContentAlignment=HorizontalAlignment.Left;var text=UI.Text(t.title,10,t.completed?UI.Muted:UI.Ink);text.TextWrapping=TextWrapping.NoWrap;text.TextTrimming=TextTrimming.CharacterEllipsis;b.Content=text;b.ToolTip=t.title;cell.Children.Add(b);AttachDrag(b,t,()=>{});}var border=new Border{Child=cell,MinHeight=week?390:100,Background=day.Month==anchor.Month?UI.Paper:UI.B("#F7F8F1"),BorderBrush=UI.Line,BorderThickness=new Thickness(0,1,1,0),Padding=new Thickness(8),AllowDrop=true};border.Drop+=(s,e)=>{string id=e.Data.GetData(DataFormats.StringFormat) as string;var t=Tasks.FirstOrDefault(x=>x.id==id);if(t!=null){t.date=key;Persist(t);}};grid.Children.Add(border);}p.Children.Add(grid);root.Children.Add(new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});return root;}
  UIElement Empty(string head,string text){var p=new StackPanel{Margin=new Thickness(20,35,20,35)};p.Children.Add(UI.Text(head,20,null,true));UI.Gap(p,10);p.Children.Add(UI.Text(text,12,UI.Muted));return p;}
  void EditNew(string state,string date){Edit(new TaskItem{category=project==""?"Без проекта":project,status=state,completed=state=="done",date=date},null);}
  void Edit(TaskItem task,string date=null){var value=task??new TaskItem{date=date,category=project==""?"Без проекта":project,status="todo"};new TaskEditor(this,value,new[]{"Без проекта"}.Concat(store.ProjectNames),t=>{try{store.Save(t,t.version);return true;}catch(Exception e){MessageBox.Show((Window)Application.Current.Windows.OfType<TaskEditor>().FirstOrDefault()??this,e.Message,"Не удалось сохранить");return false;}},t=>store.Delete(t)).ShowDialog();Refresh();RunCloudSync();}
  void Persist(TaskItem task){try{store.Save(task,task.version);Refresh();RunCloudSync();}catch(Exception e){Error(e);Refresh();}}
  void Error(Exception e){MessageBox.Show(this,e.Message,"Ритм",MessageBoxButton.OK,MessageBoxImage.Information);}
  public void PreviewView(string name){view=name;Refresh();}
